<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
import {formatDate} from '../ui/branding'
import {blankBalanceRoute,routePayload,balanceStrategies,balanceTypes,matchesBalanceType,type BalanceNode} from '../ui/balanceRoutes'
const rows=ref<any[]>([]),options=ref<any[]>([]),q=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref('')
const dialog=ref(false),editing=ref<number|null>(null),saving=ref(false),tab=ref('basic'),form=reactive(blankBalanceRoute())
const availableModelTypes=computed(()=>Object.fromEntries(Object.entries(balanceTypes).filter(([value])=>value!=='reasoning'||editing.value!==null)))
const monitoring=ref(false),detail=ref<any>(null),hours=ref(24),monitorLoading=ref(false),auto=ref(true),checking=ref<number|null>(null)
const stateLabels:Record<string,string>={healthy:'健康',unknown:'待验证',unhealthy:'异常',disabled:'已禁用',cooling:'冷却中',probe:'等待探测',unavailable:'供应商不可用',invalid:'类型或协议不兼容'}
const choices=computed(()=>options.value.filter(o=>matchesBalanceType(form.model_type,o.model_type)))
const selectedMappings=computed(()=>new Set(form.nodes.map(n=>n.mapping_id)))
const addMapping=ref<number|null>(null)
let pendingMonitor=''
let generation=0,timer:ReturnType<typeof setInterval>|undefined
async function load(){loading.value=true;error.value='';try{const d=(await api.get('/admin/balance-routes',{params:{q:q.value,page:page.value}})).data.data;rows.value=d.items;total.value=d.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(row?:any){tab.value='basic';editing.value=row?.id??null;Object.assign(form,blankBalanceRoute());try{if(row){const d=(await api.get('/admin/balance-routes/'+row.id)).data.data;for(const k of Object.keys(blankBalanceRoute()))(form as any)[k]=d[k];form.nodes=d.nodes.map((n:any)=>({...n}))}options.value=(await api.get('/admin/balance-routes/options')).data.data;dialog.value=true;addMapping.value=null}catch(e){ElMessage.error(message(e))}}
function add(){if(!addMapping.value||selectedMappings.value.has(addMapping.value))return;form.nodes.push({mapping_id:addMapping.value,weight:1,priority:0,max_concurrency:10,status:'enabled'});addMapping.value=null}
function option(id:number){return options.value.find(o=>o.mapping_id===id)}
function title(n:BalanceNode){const o=option(n.mapping_id);return o?`${o.provider_name} · ${o.logical_model} → ${o.upstream_model}`:`映射 #${n.mapping_id}（不可用）`}
async function save(){if(saving.value)return;if(!form.name.trim()||!form.model_name.trim()||!form.nodes.length){ElMessage.error('请填写名称、统一模型名称并添加节点');return}if(form.nodes.some(n=>{const current=option(n.mapping_id);return !current?!n.id:form.status==='enabled'&&n.status==='enabled'&&!matchesBalanceType(form.model_type,current.model_type)})){ElMessage.error('请移除类型不匹配或已删除的实例');return}saving.value=true;try{const body=routePayload(form,editing.value!==null);if(editing.value)await api.put('/admin/balance-routes/'+editing.value,body);else await api.post('/admin/balance-routes',body);dialog.value=false;await load();ElMessage.success('路由组已保存')}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('删除后统一模型停止提供服务；已关联模型组时需先移除授权关联。历史调用日志保留。','删除 '+row.name,{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api.delete('/admin/balance-routes/'+row.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
async function refreshMonitor(id:number){const requestKey=id+':'+hours.value;if(monitorLoading.value&&pendingMonitor===requestKey)return;pendingMonitor=requestKey;const mine=++generation;monitorLoading.value=true;try{const d=(await api.get('/admin/balance-routes/'+id,{params:{hours:hours.value},timeout:15000})).data.data;if(mine===generation)detail.value=d}catch(e){if(mine===generation)ElMessage.error(message(e))}finally{if(mine===generation)monitorLoading.value=false}}
function monitor(row:any){generation++;monitorLoading.value=false;detail.value={...row,nodes:[]};monitoring.value=true;void refreshMonitor(row.id)}
async function check(n:any){if(checking.value)return;checking.value=n.id;try{const result=(await api.post(`/admin/balance-routes/${detail.value.id}/nodes/${n.id}/check`,{}, {timeout:20000})).data.data;result.success?ElMessage.success('连接正常，已找到上游模型（未执行生成）'):ElMessage.warning(result.unsupported?'上游不支持模型列表，需通过对话测试验证':`检查失败：${result.code}`);await refreshMonitor(detail.value.id)}catch(e){ElMessage.error(message(e))}finally{checking.value=null}}
async function toggle(n:any){try{const d=detail.value;await ElMessageBox.confirm('只修改当前路由组节点，不修改供应商全局状态。',n.status==='enabled'?'停用节点':'启用节点',{type:'warning'});const next={...d,nodes:d.nodes.map((x:any)=>({...x,status:x.id===n.id?(x.status==='enabled'?'disabled':'enabled'):x.status}))};await api.put('/admin/balance-routes/'+d.id,routePayload(next,true));await refreshMonitor(d.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
watch([monitoring,auto],()=>{if(!monitoring.value){generation++;monitorLoading.value=false}if(timer)clearInterval(timer);if(monitoring.value&&auto.value)timer=setInterval(()=>{if(detail.value)void refreshMonitor(detail.value.id)},10000)})
onBeforeUnmount(()=>{generation++;if(timer)clearInterval(timer)})
onMounted(load)
</script>
<template>
<section class="module-page balance-page"><PageHeader title="负载均衡路由"><el-button type="primary" @click="open()">新增路由组</el-button></PageHeader>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div class="panel"><div class="toolbar"><el-input v-model="q" clearable placeholder="搜索路由组或统一模型名称" style="width:320px" @keyup.enter="page=1;load()"/><el-button :loading="loading" @click="page=1;load()">查询</el-button><el-button @click="q='';page=1;load()">重置</el-button></div>
<el-table :data="rows" v-loading="loading" empty-text="暂无路由组"><el-table-column prop="name" label="路由组" min-width="160"/><el-table-column prop="model_name" label="统一模型名称" min-width="200"/><el-table-column label="模型类型" width="105"><template #default="s">{{balanceTypes[s.row.model_type]}}</template></el-table-column><el-table-column label="调度策略" width="140"><template #default="s">{{balanceStrategies[s.row.strategy]}}</template></el-table-column><el-table-column prop="node_count" label="节点数" width="90"/><el-table-column prop="max_concurrency" label="最大并发" width="105"/><el-table-column label="状态" width="95"><template #default="s"><el-tag :type="s.row.status==='enabled'?'success':'info'">{{s.row.status==='enabled'?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="195" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="primary" @click="monitor(s.row)">运行监控</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table>
<el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></div></section>
<el-drawer v-model="dialog" :title="editing?'编辑路由组':'新增路由组'" size="min(1000px, 96vw)" :close-on-click-modal="!saving">
<el-tabs v-model="tab"><el-tab-pane label="基础配置" name="basic"><el-form label-position="top" class="route-grid">
<el-form-item label="路由组名称" required><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="统一模型名称" required><el-input v-model="form.model_name" :disabled="!!editing" maxlength="100" placeholder="例如 company-chat"/></el-form-item>
<el-form-item label="模型类型"><el-select v-model="form.model_type" :disabled="!!editing"><el-option v-for="(label,value) in availableModelTypes" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="路由状态"><el-switch v-model="form.status" active-value="enabled" inactive-value="disabled"/></el-form-item>
<el-form-item label="调度策略"><el-select v-model="form.strategy"><el-option v-for="(label,value) in balanceStrategies" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="路由组最大并发"><el-input-number v-model="form.max_concurrency" :min="1" :max="10000"/><span class="unit">个请求</span></el-form-item>
<el-form-item label="备注" class="span-two"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="2000"/></el-form-item></el-form><el-alert type="info" :closable="false" title="保存后使用统一模型名称调用现有 /v1 接口。普通用户需在模型组中获得此名称的授权；节点仅关联现有供应商实例，不复制密钥。"/></el-tab-pane>
<el-tab-pane label="模型节点" name="nodes"><div class="toolbar"><el-select v-model="addMapping" filterable placeholder="选择现有供应商模型实例" style="flex:1"><el-option v-for="o in choices" :key="o.mapping_id" :value="o.mapping_id" :disabled="selectedMappings.has(o.mapping_id)||!o.usable" :label="o.provider_name+' · '+o.logical_model+' → '+o.upstream_model+(o.usable?'':'（已停用或协议不支持）')"/></el-select><el-button :disabled="!addMapping||form.nodes.length>=100" @click="add">添加节点</el-button></div>
<p class="muted">节点并发、权重、优先级与启停只作用于当前路由。供应商总并发仍生效；优先级路由中数值越小越优先。</p>
<el-table :data="form.nodes" empty-text="请添加至少一个节点"><el-table-column label="模型实例" min-width="250"><template #default="s">{{title(s.row)}}</template></el-table-column><el-table-column label="权重" width="140"><template #default="s"><el-input-number v-model="s.row.weight" :min="1" :max="100" size="small" controls-position="right"/></template></el-table-column><el-table-column label="优先级" width="140"><template #default="s"><el-input-number v-model="s.row.priority" :min="0" :max="100000" size="small" controls-position="right"/></template></el-table-column><el-table-column label="最大并发" width="140"><template #default="s"><el-input-number v-model="s.row.max_concurrency" :min="1" :max="10000" size="small" controls-position="right"/></template></el-table-column><el-table-column label="启用" width="75"><template #default="s"><el-switch v-model="s.row.status" active-value="enabled" inactive-value="disabled"/></template></el-table-column><el-table-column width="70"><template #default="s"><el-button link type="danger" @click="form.nodes.splice(s.$index,1)">移除</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="健康与故障切换" name="health"><el-form label-position="top" class="route-grid"><el-form-item label="最大重试次数（不含首次）"><el-input-number v-model="form.max_retries" :min="0" :max="7"/><span class="unit">次</span></el-form-item><el-form-item label="单次请求 / SSE 建连超时"><el-input-number v-model="form.timeout_seconds" :min="1" :max="3600"/><span class="unit">秒</span></el-form-item><el-form-item label="后台健康检查间隔"><el-input-number v-model="form.health_interval" :min="10" :max="3600"/><span class="unit">秒</span></el-form-item><el-form-item label="异常冷却时间"><el-input-number v-model="form.cooldown_seconds" :min="1" :max="3600"/><span class="unit">秒</span></el-form-item><el-form-item label="连续失败摘除阈值"><el-input-number v-model="form.failure_threshold" :min="1" :max="20"/><span class="unit">次</span></el-form-item><el-form-item label="允许处理结果不确定时重试"><el-switch v-model="form.retry_uncertain"/></el-form-item></el-form>
<el-alert type="warning" :closable="false" title="默认只对明确的连接失败、鉴权拒绝和限流切换。启用不确定结果重试可能重复计费。SSE 开始后不切换节点；系统总超时仍生效。"/><p class="muted">健康检查与手动测试读取模型列表并确认上游模型名称，不验证生成能力；列表不支持、不完整或未列出模型时，请通过对话测试验证。冷却到期允许一个探测请求，成功后恢复节点。</p></el-tab-pane></el-tabs>
<template #footer><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer>
<el-drawer v-model="monitoring" :title="(detail?.name||'')+' · 运行监控'" size="min(1200px, 96vw)"><template v-if="detail"><div class="toolbar"><el-select v-model="hours" style="width:160px" @change="refreshMonitor(detail.id)"><el-option label="最近 1 小时" :value="1"/><el-option label="最近 24 小时" :value="24"/><el-option label="最近 7 天" :value="168"/></el-select><el-checkbox v-model="auto">10 秒刷新</el-checkbox><el-button :loading="monitorLoading" @click="refreshMonitor(detail.id)">刷新</el-button><router-link :to="{path:'/admin/call-logs',query:{request_model:detail.model_name}}"><el-button>调用日志</el-button></router-link></div>
<div class="route-summary"><div><span>统一模型</span><strong>{{detail.model_name}}</strong></div><div><span>策略</span><strong>{{balanceStrategies[detail.strategy]}}</strong></div><div><span>当前 / 最大并发</span><strong>{{detail.current_concurrency??'—'}} / {{detail.max_concurrency}}</strong></div></div>
<el-table :data="detail.nodes" v-loading="monitorLoading"><el-table-column label="节点" min-width="225"><template #default="s"><strong>{{s.row.provider_name}}</strong><div>{{s.row.logical_model}} → {{s.row.upstream_model}}</div></template></el-table-column><el-table-column label="健康状态" min-width="145"><template #default="s"><el-tag :type="s.row.state==='healthy'?'success':'warning'">{{stateLabels[s.row.state]||s.row.state}}</el-tag><div class="muted">{{s.row.last_error_code||'—'}}</div><small v-if="s.row.cooldown_until">{{formatDate(s.row.cooldown_until)}}</small></template></el-table-column><el-table-column label="节点并发" width="105"><template #default="s">{{s.row.current_concurrency??'—'}} / {{s.row.max_concurrency}}</template></el-table-column><el-table-column label="供应商并发" width="115"><template #default="s">{{s.row.provider_concurrency??'—'}} / {{s.row.provider_max_concurrency}}</template></el-table-column><el-table-column prop="requests" label="请求数" width="85"/><el-table-column label="成功率" width="90"><template #default="s">{{s.row.success_rate===null?'—':s.row.success_rate+'%'}}</template></el-table-column><el-table-column label="平均响应" width="115"><template #default="s">{{s.row.average_latency_ms===null?'—':s.row.average_latency_ms+' ms'}}</template></el-table-column><el-table-column label="操作" width="145" fixed="right"><template #default="s"><el-button link type="primary" :loading="checking===s.row.id" :disabled="checking!==null" @click="check(s.row)">手动检测</el-button><el-button link @click="toggle(s.row)">{{s.row.status==='enabled'?'停用':'启用'}}</el-button></template></el-table-column></el-table><p class="muted">请求量、成功率与平均响应来自当前路由节点的已落库上游尝试，包含失败和客户端取消；SSE 耗时为完整流时长。实时并发通过租约统计，历史日志保留期影响统计范围。</p></template></el-drawer>
</template>
<style scoped>
.balance-page .el-pagination{margin-top:20px}.route-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.span-two{grid-column:1/-1}.route-grid .el-select{width:100%}.unit{margin-left:10px;color:var(--muted)}.muted{font-size:13px;line-height:1.7}.route-summary{display:grid;grid-template-columns:2fr 1fr 1fr;gap:16px;margin:20px 0}.route-summary>div{border:1px solid var(--line);border-radius:8px;padding:16px}.route-summary span{display:block;color:var(--muted);margin-bottom:8px}.route-summary strong{overflow-wrap:anywhere}.el-table :deep(.el-input-number){width:110px}@media(max-width:700px){.route-grid,.route-summary{grid-template-columns:1fr}.span-two{grid-column:auto}}
</style>
